\myskip
\begin{exercise}
\textbf{Question.} The circuit below contains four $6\,\Omega$ resistors. Use node colours rather than the physical appearance of the drawing to decide which resistors are parallel. Find the current in each resistor when the battery is $12$ V.

\begin{center}
  \begin{circuitikz}[x=1cm,y=1cm,>=stealth,line width=1pt]
    \draw (0,0) to[battery1,l=$12$ V] (0,3);
    % One complete red node, including the side branch and corner.
    \draw[red,line width=1.6pt] (0,3) -- (2,3) -- (2,4) -- (5.5,4);
    \draw[red,line width=1.6pt] (2,3) -- (2,2.55);
    \draw[red,line width=1.6pt] (4,4) -- (4,3.55);
    \draw[red,line width=1.6pt] (5.5,4) -- (5.5,3.55);
    \draw (2,2.55) to[R,l=$6\,\Omega$] (2,1.0);
    \draw (2,1.0) to[short] (2,0.5);
    \draw (4,3.55) to[R,l=$6\,\Omega$] (4,2.0);
    \draw (4,2.0) to[short] (4,0.5);
    \draw (5.5,3.55) to[R,l=$6\,\Omega$] (5.5,2.0);
    \draw (5.5,2.0) to[short] (5.5,0.5);
    \draw (2,0.5) -- (5.5,0.5) -- (5.5,0);
    \draw[blue,line width=1.6pt] (5.5,0) -- (0,0);
    \draw[blue,line width=1.6pt] (2,0.5) -- (2,0);
    \draw[blue,line width=1.6pt] (4,0.5) -- (4,0);
    \draw[blue,line width=1.6pt] (5.5,0.5) -- (5.5,0);
  \end{circuitikz}
  \captionof{figure}{The red upper node and blue lower node continue through all bare-wire turns and branch leads. Every resistor is connected between the same two nodes.}
\end{center}

\textbf{Solution.} All four resistors have the same two end nodes, red and blue, so they are in parallel even though the drawing is spread out. Each resistor has the full 12 V:
\[
I_1=I_2=I_3=I_4=\frac{12}{6}=\boxed{2.0\text{ A}}.
\]
The battery current is the sum of the four branch currents:
\[
I_{\rm total}=4(2.0)=\boxed{8.0\text{ A}}.
\]
The important observation is not that the resistors look side-by-side; it is that each connects the same pair of coloured nodes.
\end{exercise}

\myskip
\begin{exercise}
\textbf{Question.} A $4\,\Omega$ resistor is connected between nodes A and B. A switch is then closed, providing a direct wire from A to B. What are the p.d. and current through the resistor after the switch is closed?

\begin{center}
  \begin{circuitikz}[x=1.1cm,y=1cm,>=stealth,line width=1pt]
    \draw (0,0) to[battery1,l=$6$ V] (0,3);
    \draw[red,line width=1.6pt] (0,3) -- (1,3);
    \draw (1,3) to[R,l=$4\,\Omega$] (4,3);
    \draw[blue,line width=1.6pt] (4,3) -- (4,0) -- (0,0);
    \draw[green!55!black,line width=1.6pt] (1,3) -- (1,4) -- (4,4) -- (4,3);
    \node[red,above left] at (1,3) {A};
    \node[blue,above right] at (4,3) {B};
    \node[green!55!black,above] at (2.5,4) {closed switch / ideal wire};
  \end{circuitikz}
  \captionof{figure}{The green wire joins A and B directly, so A and B become one node even though the resistor remains drawn below it.}
\end{center}

\textbf{Solution.} Follow the green wire: it connects A to B without crossing a component. Therefore A and B must receive the same colour and have the same potential:
\[
V_{AB}=\boxed{0\text{ V}},\qquad I_R=\frac{V_{AB}}{4}=\boxed{0\text{ A}}.
\]
The resistor is short-circuited. The 6 V source is not itself short-circuited here: the green wire bypasses only the resistor, not the battery.
\end{exercise}

