    \node[font=\footnotesize] at (2.45,0.45) {no dot: separate};
  \end{scope}
\end{tikzpicture}
\captionof{figure}{Follow bare wire through corners and branches. Start a new colour only after a component or break.}
\end{center}

\begin{enumerate}[itemsep=2pt,topsep=3pt]
  \item Colour every connected stretch of bare wire the same colour.
  \item Stop at a component, open switch, or unjoined crossing; continue with a new colour.
  \item Same two colours on two components $\Rightarrow$ \textbf{parallel}. Same colour at both ends of one component $\Rightarrow$ \textbf{short-circuited}.
\end{enumerate}

