\begin{exercise}
\textbf{Question.} Three $2\,\Omega$ resistors are drawn spread across a circuit and connected to a $4$ V battery as shown. They look separate, so a student adds them as if in series. Use the colouring method to find how they are really connected, and find the total current from the battery.

\begin{center}
  \begin{circuitikz}[x=1cm, y=1cm, >=stealth, line width=1pt]
    \draw (0,0) to[battery1, l=$4$ V] (0,3);
    % Every bare wire in the upper node is red, including each branch lead.
    \draw[red,line width=1.6pt] (0,3) -- (6,3);
    \draw[red,line width=1.6pt] (2,3) -- (2,2.55);
    \draw[red,line width=1.6pt] (4,3) -- (4,2.55);
    \draw[red,line width=1.6pt] (6,3) -- (6,2.55);
    % Every bare wire in the lower node is blue, including each branch lead.
    \draw[blue,line width=1.6pt] (0,0) -- (6,0);
    \draw[blue,line width=1.6pt] (2,0) -- (2,0.45);
    \draw[blue,line width=1.6pt] (4,0) -- (4,0.45);
    \draw[blue,line width=1.6pt] (6,0) -- (6,0.45);
    \draw (2,2.55) to[R, l=$2\,\Omega$] (2,0.45);
    \draw (4,2.55) to[R, l=$2\,\Omega$] (4,0.45);
    \draw (6,2.55) to[R, l=$2\,\Omega$] (6,0.45);
    \node[red,above,font=\footnotesize] at (3,3.15) {entire upper node: same potential ($+$)};
    \node[blue,below,font=\footnotesize] at (3,-0.15) {entire lower node: same potential ($-$)};
  \end{circuitikz}
  \captionof{figure}{Colouring the two rails shows every resistor runs from the red potential to the blue potential. Same pair of colours $\Rightarrow$ all three are in parallel.}
\end{center}

\textbf{Solution.} The top rail is all one colour (red) and the bottom rail is all one colour (blue), with no component breaking either rail. Every resistor therefore connects the \emph{same} two potentials, red to blue: the three are in \textbf{parallel}, not in series. Each one has the full $4$ V across it, so by $I=V/R$ each carries
\[
I=\frac{4}{2}=2\text{ A},
\]
and the battery current is the sum of the three branches,
\[
I_{\rm total}=2+2+2=\boxed{6\text{ A}}.
\]
(The series guess would have given $R_{\rm eq}=6\,\Omega$ and only $0.67$ A -- nine times too small.)
\end{exercise}

\myskip
\begin{exercise}
\textbf{Question.} In the circuit below a $12$ V battery drives three resistors, $R_1=2\,\Omega$, $R_2=4\,\Omega$ and $R_3=4\,\Omega$. A plain wire runs from point C to point D, straight over $R_2$. Find the current drawn from the battery and the current in $R_2$.

\begin{center}
  \begin{circuitikz}[x=1.05cm, y=1cm, >=stealth, line width=1pt]
    \draw (0,0) to[battery1, l=$12$ V] (0,3);
    % A (red) -- R1 -- C
    \draw[red,line width=1.6pt] (0,3) -- (1,3);
    \draw (1,3) to[R, l=$R_1{=}2\,\Omega$] (3,3);
    % C -- R2 -- D  (main rail)
    \draw (3,3) to[R, l=$R_2{=}4\,\Omega$] (5,3);
    % shorting wire C -> D, drawn overhead in green
    \draw[green!55!black,line width=1.6pt] (3,3) -- (3,4) -- (5,4) -- (5,3);
    % D -- R3 -- corner -- back to B
    \draw (5,3) to[R, l=$R_3{=}4\,\Omega$] (7,3);
    % The right side and entire return rail are one continuous blue node.
    \draw[blue,line width=1.6pt] (7,3) -- (7,0) -- (0,0);
    % coloured node dots
    \node[circle,fill=red,inner sep=1.5pt] at (0,3) {};
    \node[circle,fill=green!55!black,inner sep=1.5pt] at (3,3) {};
    \node[circle,fill=green!55!black,inner sep=1.5pt] at (5,3) {};
    \node[circle,fill=blue,inner sep=1.5pt] at (7,0) {};
    \node[red,above left,font=\footnotesize] at (0,3) {A};
    \node[green!55!black,above,font=\footnotesize] at (3,4.05) {C = D (one wire, one potential)};
    \node[blue,below right,font=\footnotesize] at (7,0) {B};
  \end{circuitikz}
  \captionof{figure}{The green wire joins C and D with no component in between, so C and D are the \emph{same} node (one colour). $R_2$ then has the same colour on both ends.}
\end{center}

\textbf{Solution.} Colour the wires. From the $+$ terminal A out to the left of $R_1$ is one potential (red). The green wire ties C directly to D, so C and D are the \emph{same} node -- give them one colour (green). From the right of $R_3$ back to the $-$ terminal B is the last potential (blue).

Now look at $R_2$: both of its ends, C and D, are green -- the \emph{same} potential. So the p.d. across $R_2$ is zero and
\[
I_{R_2}=\frac{0}{4}=\boxed{0\text{ A}}.
\]
$R_2$ is short-circuited by the wire and carries no current at all. With $R_2$ removed, only $R_1$ (red$\to$green) and $R_3$ (green$\to$blue) are left, and they share the same current, so they are in series:
\[
R_{\rm eq}=R_1+R_3=2+4=6\,\Omega,
\qquad
I=\frac{12}{6}=\boxed{2\text{ A}}.
\]
The tempting mistake is to add all three ($2+4+4=10\,\Omega$, giving $1.2$ A). Colouring the wires shows immediately that $R_2$ is bypassed, so the real answer is $2$ A.
\end{exercise}

