\begin{exercise}
\textbf{Question.} The circuit below contains four $6\,\Omega$ resistors. Use node colours rather than the physical appearance of the drawing to decide which resistors are parallel. Find the current in each resistor when the battery is $12$ V.

\begin{center}
  \begin{circuitikz}[x=1cm,y=1cm,>=stealth,line width=1pt]
    \draw (0,0) to[battery1,l=$12$ V] (0,3);
    % One complete red node, including the side branch and corner.
    \draw[red,line width=1.6pt] (0,3) -- (2,3) -- (2,4) -- (5.5,4);
    \draw[red,line width=1.6pt] (2,3) -- (2,2.55);
    \draw[red,line width=1.6pt] (3,4) -- (3,3.55);
    \draw[red,line width=1.6pt] (4,4) -- (4,3.55);
    \draw[red,line width=1.6pt] (5.5,4) -- (5.5,3.55);
    \draw (2,2.55) to[R,l=$6\,\Omega$] (2,1.0);
    \draw[blue,line width=1.6pt] (2,1.0) -- (2,0);
    \draw (3,3.55) to[R,l=$6\,\Omega$] (3,2.0);
    \draw[blue,line width=1.6pt] (3,2.0) -- (3,0);
    \draw (4,3.55) to[R,l=$6\,\Omega$] (4,2.0);
    \draw[blue,line width=1.6pt] (4,2.0) -- (4,0);
    \draw (5.5,3.55) to[R,l=$6\,\Omega$] (5.5,2.0);
    \draw[blue,line width=1.6pt] (5.5,2.0) -- (5.5,0);
    \draw[blue,line width=1.6pt] (0,0) -- (5.5,0);
  \end{circuitikz}
  \captionof{figure}{The red upper node and blue lower node continue through all bare-wire turns and branch leads. Every resistor is connected between the same two nodes.}
\end{center}

\textbf{Solution.} All four resistors have the same two end nodes, red and blue, so they are in parallel even though the drawing is spread out. Each resistor has the full 12 V:
\[
I_1=I_2=I_3=I_4=\frac{12}{6}=\boxed{2.0\text{ A}}.
\]
The battery current is the sum of the four branch currents:
\[
I_{\rm total}=4(2.0)=\boxed{8.0\text{ A}}.
\]
The important observation is not that the resistors look side-by-side; it is that each connects the same pair of coloured nodes.
\end{exercise}

\myskip
\begin{exercise}
\textbf{Question.} A $2\,\Omega$ resistor is in series with a section containing a $4\,\Omega$ resistor. A switch is closed to provide a direct wire from A to B across only the $4\,\Omega$ resistor. What are the p.d. and current through the $4\,\Omega$ resistor after the switch is closed?

\begin{center}
  \begin{circuitikz}[x=1.05cm,y=1cm,>=stealth,line width=1pt]
    \draw (0,0) to[battery1,l=$6$ V] (0,3);
    \draw[red,line width=1.6pt] (0,3) -- (0.7,3);
    \draw (0.7,3) to[R,l=$2\,\Omega$] (2.5,3);
    % Closing the switch makes A, B and every bypass segment one green node.
    \draw[green!55!black,line width=1.6pt] (2.5,3) -- (3,3);
    \draw (3,3) to[R,l=$4\,\Omega$] (5.5,3);
    \draw[green!55!black,line width=1.6pt] (5.5,3) -- (6,3);
    \draw[green!55!black,line width=1.6pt] (3,3) -- (3,4) -- (5.5,4) -- (5.5,3);
    \draw[blue,line width=1.6pt] (6,3) -- (6,0) -- (0,0);
    \node[green!55!black,above left] at (3,3) {A};
    \node[green!55!black,above right] at (5.5,3) {B};
    \node[green!55!black,above] at (4.25,4) {closed switch / ideal wire};
  \end{circuitikz}
  \captionof{figure}{After the switch closes, the entire bypass path and both resistor terminals A and B are one green node. The $2\,\Omega$ resistor remains between the red and green nodes, so the source is not short-circuited.}
\end{center}

\textbf{Solution.} Follow the green wire: it connects A to B without crossing a component. Therefore A and B receive the same colour and have the same potential:
\[
V_{AB}=\boxed{0\text{ V}},\qquad I_{4\Omega}=\frac{V_{AB}}{4}=\boxed{0\text{ A}}.
\]
The $4\,\Omega$ resistor is short-circuited. Current can still flow through the battery, the $2\,\Omega$ resistor and the bypass wire; the source current is $6/2=3$ A.
\end{exercise}

